/**
 * The instant a workspace deleted at or before it has used up its retention
 * window. Restore and the purge both compare against this one value, so they
 * can never disagree about whether a workspace is still recoverable.
 */
export function deletedWorkspaceCutoff(now: Date): IsoTimestamp {
  return toIsoTimestamp(
    new Date(now.getTime() - DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY),
  );
}

/** True once a deleted workspace's retention window has closed. */
function retentionClosed(org: Organization, now: Date): boolean {
  return (
    org.archivedAt !== null && org.archivedAt <= deletedWorkspaceCutoff(now)
  );
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The workspace is kept, inert,
 * for `DELETED_WORKSPACE_RETENTION_DAYS` so it can be restored.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  assertNotArchived("Organization", input.orgId, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const deleted = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...envelope(input.orgId, actor.userId),
    slug: deleted.slug,
  });

  return deleted;
}

/**
 * Brings a deleted workspace back while its retention window is open. A
 * deleted workspace has no `Actor` to resolve (every sign-in and membership
 * read hides it), so the caller is identified by user id and the membership is
 * read here. A workspace that is not deleted is returned unchanged.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  if (retentionClosed(org, new Date())) {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan({ userId, orgId, role: member.role }, "org:restore", orgResource(orgId));

  if (!isArchived(org)) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

