    const overdue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId, tenant.project.id, { title: "late", assigneeId: tenant.userIds.member, dueAt: PAST }),
    );

    const deleted = await orgService.deleteOrganization(tenant.actors.owner, { orgId, confirmSlug: slug });
    off();

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ orgId, actorId: tenant.userIds.owner, slug });

    const page = await activityRepo.listActivity({ orgId, limit: 100, cursor: null });
    const row = page.items.find((e) => e.action === "organization.deleted");
    expect(row).toMatchObject({ subjectKind: "organization", subjectId: orgId, actorId: tenant.userIds.owner });

    await expect(
      orgService.deleteOrganization(tenant.actors.owner, { orgId, confirmSlug: slug }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    (globalThis as Record<string, unknown>).__overdueId = overdue.id;
  });

  it("keeps the slug reserved and hides the workspace from sign-in and listings", async () => {
    expect(await orgRepo.findOrgBySlug(slug)).toBeNull();
    expect(await orgRepo.listTakenOrgSlugs(slug)).toContain(slug);
    const mine = await orgService.listOrganizationsForUser(tenant.userIds.owner);
    expect(mine.map((o) => o.id)).not.toContain(orgId);
  });

  it("creates no notifications and accepts no invitation", async () => {
    const created = await notificationService.notify(orgId, "member_joined", [tenant.userIds.member], {
      title: "t", body: "b", href: "/", actorId: null,
    });
    expect(created).toEqual([]);

    const token = "scratch-token-accept";
    await invitationRepo.insertInvitation(
      orgId,
      { orgId, email: "new@gone.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );
    const newcomer = await userRepo.insertUser({ email: "new@gone.test", name: "New", passwordHash: "seed" });

    await expect(invitationService.acceptInvitation(newcomer.id, { token })).rejects.toBeInstanceOf(NotFoundError);
    const stillPending = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(stillPending?.acceptedAt).toBeNull();
  });

  it("is left alone by the background jobs", async () => {
    const overdueSeen: string[] = [];
    const off = subscribe("issue.overdue", (p: TaskflowEventMap["issue.overdue"]) => { overdueSeen.push(p.issueId); });
    await runOverdueIssueJob(NOW);
    off();
    expect(overdueSeen).not.toContain((globalThis as Record<string, unknown>).__overdueId);

    const ids = await usageRepo.listOrgIdsForRollup(100);
    expect(ids).not.toContain(orgId);

    const trials = await subscriptionRepo.listTrialsEndingBefore(
      toIsoTimestamp(new Date(Date.now() + 60 * DAY)),
    );
    expect(trials.map((s) => s.orgId)).not.toContain(orgId);

    await webhookRepo.insertEndpoint(
      { orgId, url: "https://example.test/hook", eventTypes: ["issue.created"] } as never,
      "secret",
    );
    const endpoints = await webhookRepo.listEndpoints(orgId);
    await webhookRepo.enqueueDelivery(orgId, endpoints[0]!.id, "issue.created", "{}");
    await runWebhookDeliveryJob(new Date());
    const rows = getDb().select().from(webhookDeliveries).all().filter((r) => r.orgId === orgId);
    expect(rows.every((r) => r.status === "failed")).toBe(true);

    await runUsageRollupJob(NOW);
    await runTrialExpiryJob(new Date(Date.now() + 60 * DAY));
  });
});

describe("restoring", () => {
  it("throws NotFoundError for a user who is not a member", async () => {
    const stranger = await userRepo.insertUser({ email: "stranger@gone.test", name: "S", passwordHash: "seed" });
    await expect(orgService.restoreOrganization(stranger.id, orgId)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("throws PermissionDeniedError for a member who is not an owner", async () => {
    await expect(orgService.restoreOrganization(tenant.userIds.admin, orgId)).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("restores for the owner, publishes organization.restored and audits it", async () => {
    const seen: TaskflowEventMap["organization.restored"][] = [];
    const off = subscribe("organization.restored", (p) => { seen.push(p); });

    const restored = await orgService.restoreOrganization(tenant.userIds.owner, orgId);
    off();

    expect(restored.archivedAt).toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ orgId, actorId: tenant.userIds.owner, slug });
    expect(await orgRepo.findOrgBySlug(slug)).not.toBeNull();
    const mine = await orgService.listOrganizationsForUser(tenant.userIds.owner);
    expect(mine.map((o) => o.id)).toContain(orgId);

    const page = await activityRepo.listActivity({ orgId, limit: 100, cursor: null });
    expect(page.items.some((e) => e.action === "organization.restored")).toBe(true);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const seen: unknown[] = [];
    const off = subscribe("organization.restored", (p) => { seen.push(p); });
    const again = await orgService.restoreOrganization(tenant.userIds.owner, orgId);
    off();
    expect(again.id).toBe(orgId);
    expect(seen).toHaveLength(0);
  });

  it("is refused once the retention window has closed, even before the purge", async () => {
    await orgService.deleteOrganization(tenant.actors.owner, { orgId, confirmSlug: slug });
    const closed = new Date(Date.now() + (DELETED_WORKSPACE_RETENTION_DAYS + 1) * DAY);
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(closed);
    await expect(orgService.restoreOrganization(tenant.userIds.owner, orgId)).rejects.toBeInstanceOf(NotFoundError);
    vi.useRealTimers();
  });
});

describe("purging", () => {
  it("does not purge a workspace deleted less than the window ago", async () => {
    await runCleanupArchivedJob(new Date(Date.now() + (DELETED_WORKSPACE_RETENTION_DAYS - 1) * DAY));
    expect(await orgRepo.findOrgById(orgId)).not.toBeNull();
  });

  it("removes the workspace and every row that belongs to it once the window has closed", async () => {
    const result = await runCleanupArchivedJob(new Date(Date.now() + (DELETED_WORKSPACE_RETENTION_DAYS + 1) * DAY));
    expect(result.failed).toBe(0);

    expect(await orgRepo.findOrgById(orgId)).toBeNull();
    expect(await orgRepo.listTakenOrgSlugs(slug)).toEqual([]);
    const page = await activityRepo.listActivity({ orgId, limit: 100, cursor: null });
    expect(page.total).toBe(0);
    expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(orgId);
    expect(await userRepo.findUserById(tenant.userIds.owner)).not.toBeNull();

    const replacement = await orgService.createOrganization(tenant.userIds.owner, {
      name: "Again", slug, plan: "free",
    } as never);
    expect(replacement.slug).toBe(slug);
  });

  it("refuses to restore a purged workspace", async () => {
    await expect(orgService.restoreOrganization(tenant.userIds.owner, orgId)).rejects.toBeInstanceOf(NotFoundError);
  });
});

